 1549      ///
 1550      /// If all work has been exhausted, then this returns None. The worker
 1551      /// should then subsequently quit.
 1552      fn get_work(&mut self) -> Option<Work> {
 1553          let mut value = self.rx.try_recv();
 1554          loop {
 1555              // Simulate a priority channel: If quit_now flag is set, we can
 1556              // receive only quit messages.
 1557              if self.is_quit_now() {
 1558                  value = Ok(Message::Quit)
 1559              }
 1560              match value {
 1561                  Ok(Message::Work(work)) => {
 1562                      return Some(work);
 1563                  }
 1564                  Ok(Message::Quit) => {
 1565                      // Repeat quit message to wake up sleeping threads, if
 1566                      // any. The domino effect will ensure that every thread
 1567                      // will quit.
 1568                      self.tx.send(Message::Quit).unwrap();
 1569                      return None;
 1570                  }
 1571                  Err(TryRecvError::Empty) => {
 1572                      // Once num_pending reaches 0, it is impossible for it to
 1573                      // ever increase again. Namely, it only reaches 0 once
 1574                      // all jobs have run such that no jobs have produced more
 1575                      // work. We have this guarantee because num_pending is
 1576                      // always incremented before each job is submitted and only
 1577                      // decremented once each job is completely finished.
 1578                      // Therefore, if this reaches zero, then there can be no
 1579                      // other job running.
